import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.Bj-lFevX.js";const u=JSON.parse('{"title":"Extension Point Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/extension-points.md","filePath":"reference/extension-points.md"}'),s={name:"reference/extension-points.md"};function n(i,e,l,h,p,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="extension-point-reference" tabindex="-1">Extension Point Reference <a class="header-anchor" href="#extension-point-reference" aria-label="Permalink to &quot;Extension Point Reference&quot;">​</a></h1><p>This page is generated automatically from the <code>swagger-php</code> sources.</p><p>For improvements head over to <a href="https://github.com/zircote/swagger-php" target="_blank" rel="noreferrer">GitHub</a> and create a PR 😉</p><p>What the assembler, the attribute factory and the resolver run by default at each extension point, in the order they run. For adding your own, see <a href="/swagger-php/guide/extension-points.html">Extension points</a>.</p><p><a href="/swagger-php/reference/augmenters.html">Augmenters</a>, <a href="/swagger-php/reference/mergers.html">mergers</a> and <a href="/swagger-php/reference/architecture.html#compilers">compilers</a> have their own listings.</p><h2 id="default-translators" tabindex="-1">Default Translators <a class="header-anchor" href="#default-translators" aria-label="Permalink to &quot;Default Translators&quot;">​</a></h2><h3 id="defaultattributetranslator" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Assembler/DefaultAttributeTranslator.php" target="_blank" rel="noreferrer">DefaultAttributeTranslator</a> <a class="header-anchor" href="#defaultattributetranslator" aria-label="Permalink to &quot;[DefaultAttributeTranslator](https://github.com/zircote/swagger-php/tree/master/src/Assembler/DefaultAttributeTranslator.php)&quot;">​</a></h3><p>Default implementation handling native (OpenApi) attributes.</p><h3 id="optionalpropertyattributetranslator" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Assembler/OptionalPropertyAttributeTranslator.php" target="_blank" rel="noreferrer">OptionalPropertyAttributeTranslator</a> <a class="header-anchor" href="#optionalpropertyattributetranslator" aria-label="Permalink to &quot;[OptionalPropertyAttributeTranslator](https://github.com/zircote/swagger-php/tree/master/src/Assembler/OptionalPropertyAttributeTranslator.php)&quot;">​</a></h3><p>Add the required <code>OA\\Property</code> on schema properties that only have:</p><ul><li>an <code>OA\\Schema</code></li><li>an <code>OA\\Encoding</code></li></ul><p>This is what implements the implicit <code>OA\\Property</code> shortcut. The <code>OA\\MediaType</code> shortcuts are the <code>Augmenter\\Shortcuts</code> augmenter; the <code>OA\\Parameter</code> ones are plain subclasses.</p><p>Not in a class carrying <code>OA\\Components</code>: there a schema on a property is a component of its own, named after the property, so it is left for the holder to absorb.</p><h3 id="operationmethodstranslator" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Assembler/OperationMethodsTranslator.php" target="_blank" rel="noreferrer">OperationMethodsTranslator</a> <a class="header-anchor" href="#operationmethodstranslator" aria-label="Permalink to &quot;[OperationMethodsTranslator](https://github.com/zircote/swagger-php/tree/master/src/Assembler/OperationMethodsTranslator.php)&quot;">​</a></h3><p>Split an <code>OA\\Operation</code> declaring <code>methods:</code> into one operation per method.</p><p>The first method keeps the declared operation, every other one gets a <code>copy()</code> of it. When the split operation is the only operation on its method, what would nest into it is set to <code>Fan::All</code> where it leaves <code>fan</code> unset: its siblings, and the attributes on the method&#39;s PHP parameters, or on <code>__invoke</code>&#39;s for an operation declared on an invokable class. So each method gets the whole description. Next to other operations nothing is fanned, and an attribute that could go into more than one of them is the usual ambiguity.</p><p>An explicit <code>operationId</code> on several methods has to tell them apart with <code>{method}</code>, which <code>Augmenter\\OperationIdTemplates</code> expands. Without it, it is dropped with a warning and each method gets a generated one.</p><p>A translator creating <code>methods:</code> operations itself has to run before this one: <code>insert()</code> it into the translators ahead of this class rather than <code>add()</code> it.</p><h2 id="default-resolvers" tabindex="-1">Default Resolvers <a class="header-anchor" href="#default-resolvers" aria-label="Permalink to &quot;Default Resolvers&quot;">​</a></h2><h3 id="reflection" tabindex="-1"><a href="https://github.com/zircote/swagger-php/tree/master/src/Resolver/Reflection.php" target="_blank" rel="noreferrer">Reflection</a> <a class="header-anchor" href="#reflection" aria-label="Permalink to &quot;[Reflection](https://github.com/zircote/swagger-php/tree/master/src/Resolver/Reflection.php)&quot;">​</a></h3><p>Resolves missing components by collecting the referenced class with the assembler in use.</p><p>This makes listing all related classes as builder sources optional; adding a single controller is enough as long as everything it references (directly or transitively) carries spec attributes.</p><p>A FQCN is considered resolved if the specification knows it once collected. Classes without any spec attributes are left to the next resolver in the chain.</p>',23)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
